#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int r, g;
    cin >> r >> g;

    const int MOD = 1000000007;
    const long long available = static_cast<long long>(r) + g;

    int height = 0;
    while (1LL * (height + 1) * (height + 2) / 2 <= available)
        ++height;

    const long long total = 1LL * height * (height + 1) / 2;

    vector<int> dp(r + 1);
    dp[0] = 1;

    for (int level = 1; level <= height; ++level) {
        for (int used = r; used >= level; --used) {
            dp[used] += dp[used - level];
            if (dp[used] >= MOD)
                dp[used] -= MOD;
        }
    }

    const int lower = max(0LL, total - g);
    const int upper = min<long long>(r, total);

    int answer = 0;
    for (int used = lower; used <= upper; ++used) {
        answer += dp[used];
        if (answer >= MOD)
            answer -= MOD;
    }

    cout << answer << '\n';
    return 0;
}

