int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int r, g;
    cin >> r >> g;

    int height = 0;
    while ((height + 1LL) * (height + 2) / 2 <= r + g) {
        ++height;
    }

    vector<ll> dp(r + 1, 0);
    dp[0] = 1;

    int total = 0;
    for (int level = 1; level <= height; ++level) {
        total += level;
        for (int red = min(r, total); red >= level; --red) {
            dp[red] = (dp[red] + dp[red - level]) % MOD;
        }
    }

    ll answer = 0;
    for (int red = max(0, total - g); red <= min(r, total); ++red) {
        answer = (answer + dp[red]) % MOD;
    }

    cout << answer << '\n';
    return 0;
}

