    int h = 0;
    while ((h + 1LL) * (h + 2) / 2 <= r + g)
        ++h;

    vector<ll> dp(r + 1, 0);
    dp[0] = 1;

    int total = 0;
    for (int level = 1; level <= h; ++level) {
        total += level;
        for (int red = min(r, total); red >= level; --red) {
            dp[red] = (dp[red] + dp[red - level]) % MOD;
        }
    }

    ll answer = 0;
